-- ═══════════════════════════════════════════════════════════════════
-- Backfill student_subject_progress from the bagrut roadmap sheet + the
-- civics grades file. Adds details jsonb (verbatim). Tightens RLS to
-- admin-only (choice A). Idempotent: safe to re-run (ON CONFLICT UPDATE).
-- Does NOT delete/re-import students and does NOT touch student_bagrut_data.
-- ═══════════════════════════════════════════════════════════════════

-- 1. Schema: verbatim details field
ALTER TABLE public.student_subject_progress ADD COLUMN IF NOT EXISTS details jsonb;

-- 2. RLS -> admin only (drop all existing policies, recreate admin-only)
DO $$ DECLARE p record; BEGIN
  FOR p IN SELECT policyname FROM pg_policies
           WHERE schemaname='public' AND tablename='student_subject_progress'
  LOOP EXECUTE format('DROP POLICY %I ON public.student_subject_progress', p.policyname); END LOOP;
END $$;
CREATE POLICY "Admins read progress"   ON public.student_subject_progress FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins insert progress" ON public.student_subject_progress FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins update progress" ON public.student_subject_progress FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins delete progress" ON public.student_subject_progress FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin'));

-- 3. Ensure canonical subjects exist
INSERT INTO public.subjects (subject_name)
SELECT v FROM (VALUES ('תנ״ך'),('לשון'),('היסטוריה'),('אנגלית'),('מתמטיקה'),('חינוך גופני'),('ספרות'),('אזרחות')) t(v)
ON CONFLICT (subject_name) DO NOTHING;

-- 4. MAIN backfill (466 subject rows from the roadmap sheet)
