INSERT INTO public.student_subject_progress (student_id, subject_id, grade, details)
SELECT DISTINCT ON (s.id, subj.id) s.id, subj.id, p.grade, p.details
FROM _prog p
JOIN public.students s ON s.full_name = p.name AND s.class_name = p.cls
JOIN public.subjects subj ON subj.subject_name = p.subject
ORDER BY s.id, subj.id
ON CONFLICT (student_id, subject_id) DO UPDATE SET grade = EXCLUDED.grade, details = EXCLUDED.details;

-- 5. CIVICS backfill (66 rows: match by national_id, else name+class)
CREATE TEMP TABLE _civ AS
SELECT e->>'n' AS name, e->>'id' AS nid, e->>'c' AS cls,
       CASE WHEN e->>'grade' ~ '^[0-9.]+$' THEN (e->>'grade')::numeric ELSE NULL END AS grade,
       e->'details' AS details, NULL::uuid AS student_id
