UPDATE _civ c SET student_id = s.id FROM public.students s
  WHERE c.nid IS NOT NULL AND c.nid <> '' AND s.national_id = c.nid;
UPDATE _civ c SET student_id = s.id FROM public.students s
  WHERE c.student_id IS NULL AND s.full_name = c.name AND s.class_name = c.cls;

DO $$ DECLARE m int; u int; unl text;
BEGIN
  SELECT count(*) FILTER (WHERE student_id IS NOT NULL),
         count(*) FILTER (WHERE student_id IS NULL) INTO m, u FROM _civ;
  SELECT string_agg(name, ', ') INTO unl FROM _civ WHERE student_id IS NULL;
  RAISE NOTICE 'CIVICS matched=%, unmatched=%, unmatched_names=[%]', m, u, COALESCE(unl,'none');
END $$;

INSERT INTO public.student_subject_progress (student_id, subject_id, grade, details)
SELECT DISTINCT ON (c.student_id) c.student_id,
       (SELECT id FROM public.subjects WHERE subject_name='אזרחות'), c.grade, c.details
FROM _civ c WHERE c.student_id IS NOT NULL
ORDER BY c.student_id
ON CONFLICT (student_id, subject_id) DO UPDATE SET grade = EXCLUDED.grade, details = EXCLUDED.details;

DO $$ DECLARE p int; BEGIN
  SELECT count(*) INTO p FROM public.student_subject_progress;
  RAISE NOTICE 'TOTAL student_subject_progress rows now = %', p;
END $$;

DROP TABLE _prog; DROP TABLE _civ;
